{
  "correction_rules": [
    "Reduce forecast bias when sentiment is negative (sentiment < 0) — model tends to overestimate prices.",
    "Adjust downward for recent spikes (last 5-7 days) — model often overshoots after sharp increases.",
    "Apply mean reversion correction if forecast deviates > ±10% from 30-day moving average — especially when sentiment is neutral or slightly positive.",
    "Lower forecast for long-term horizons (e.g., 30d) when sentiment is weak or negative — model overconfident in trending periods.",
    "Increase forecast sensitivity to recent low prices when sentiment is positive — model underreacts to downward momentum.",
    "Apply lag correction: if true outcome is below forecast, reduce forecast by 5-10% for next period if sentiment remains stable or negative."
  ]
}
